-- =====================================================================
-- Student Freelance Marketplace – Sprint 5: Tải CV dạng file PDF
-- Cơ sở dữ liệu: student_freelance_marketplace
--
-- Mục đích: sinh viên chọn file CV (PDF, tối đa 5 MB) thay vì dán liên kết.
-- File được lưu trong bảng cv_files (cột data, kiểu MEDIUMBLOB) để vẫn còn
-- sau mỗi lần triển khai lại trên Railway (ổ đĩa của ứng dụng bị xóa khi deploy).
-- student_profiles.cv_url / applications.cv_url lưu đường dẫn "/api/files/cv/{id}".
-- Chỉ chủ file, nhà tuyển dụng nhận đơn có CV đó và ADMIN được xem file.
--
-- Thứ tự chạy:
--   CSDL đang có dữ liệu : sprint5-employment-type.sql → sprint5-job-moderation.sql → file này
--   CSDL mới             : schema.sql → demo-data.sql → sprint4-job-work-time.sql
--                          → sprint5-employment-type.sql → sprint5-job-moderation.sql → file này
--
-- An toàn khi chạy lại:
--   - CREATE TABLE IF NOT EXISTS, không DROP, không DELETE.
--   - 2 file CV demo chỉ INSERT khi chưa có.
--   - Chỉ thay liên kết CV giả "https://example.com/cv/..." của 2 sinh viên demo
--     bằng file CV thật; CV người dùng tự nhập không bị đụng tới.
-- =====================================================================

USE `student_freelance_marketplace`;

CREATE TABLE IF NOT EXISTS `cv_files` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `owner_id` bigint NOT NULL,
  `file_name` varchar(255) COLLATE utf8mb4_unicode_ci NOT NULL,
  `content_type` varchar(100) COLLATE utf8mb4_unicode_ci NOT NULL,
  `size_bytes` int NOT NULL,
  `data` mediumblob NOT NULL,
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `idx_cv_files_owner` (`owner_id`),
  CONSTRAINT `fk_cv_files_owner` FOREIGN KEY (`owner_id`) REFERENCES `users` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `chk_cv_files_size` CHECK (((`size_bytes` > 0) and (`size_bytes` <= 5242880)))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ---------------------------------------------------------------------
-- CV demo (PDF thật, mở xem được) cho 2 sinh viên demo
-- ---------------------------------------------------------------------
SET @sv_minhanh = (SELECT id FROM users WHERE email = 'minhanh.demo@example.com');
SET @sv_quochuy = (SELECT id FROM users WHERE email = 'quochuy.demo@example.com');

INSERT INTO cv_files (owner_id, file_name, content_type, size_bytes, data)
SELECT @sv_minhanh, 'CV_Nguyen_Minh_Anh.pdf', 'application/pdf', 48293,
       
FROM DUAL WHERE @sv_minhanh IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM cv_files WHERE owner_id = @sv_minhanh AND file_name = 'CV_Nguyen_Minh_Anh.pdf');

INSERT INTO cv_files (owner_id, file_name, content_type, size_bytes, data)
SELECT @sv_quochuy, 'CV_Tran_Quoc_Huy.pdf', 'application/pdf', 48181,
       
FROM DUAL WHERE @sv_quochuy IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM cv_files WHERE owner_id = @sv_quochuy AND file_name = 'CV_Tran_Quoc_Huy.pdf');

SET @cv_minhanh = (SELECT MIN(id) FROM cv_files WHERE owner_id = @sv_minhanh AND file_name = 'CV_Nguyen_Minh_Anh.pdf');
SET @cv_quochuy = (SELECT MIN(id) FROM cv_files WHERE owner_id = @sv_quochuy AND file_name = 'CV_Tran_Quoc_Huy.pdf');

-- Thay liên kết CV giả bằng file thật (hồ sơ và các đơn đã ứng tuyển)
SET @old_safe_updates = @@SQL_SAFE_UPDATES;
SET SQL_SAFE_UPDATES = 0;
UPDATE student_profiles SET cv_url = CONCAT('/api/files/cv/', @cv_minhanh)
WHERE user_id = @sv_minhanh AND @cv_minhanh IS NOT NULL AND (cv_url IS NULL OR cv_url LIKE 'https://example.com/cv/%');
UPDATE student_profiles SET cv_url = CONCAT('/api/files/cv/', @cv_quochuy)
WHERE user_id = @sv_quochuy AND @cv_quochuy IS NOT NULL AND (cv_url IS NULL OR cv_url LIKE 'https://example.com/cv/%');
UPDATE applications SET cv_url = CONCAT('/api/files/cv/', @cv_minhanh)
WHERE student_id = @sv_minhanh AND @cv_minhanh IS NOT NULL AND cv_url LIKE 'https://example.com/cv/%';
UPDATE applications SET cv_url = CONCAT('/api/files/cv/', @cv_quochuy)
WHERE student_id = @sv_quochuy AND @cv_quochuy IS NOT NULL AND cv_url LIKE 'https://example.com/cv/%';
SET SQL_SAFE_UPDATES = @old_safe_updates;

-- ---------------------------------------------------------------------
-- Kiểm tra kết quả
-- ---------------------------------------------------------------------
SELECT f.id, u.email, f.file_name, f.size_bytes AS kich_thuoc_byte, p.cv_url
FROM cv_files f
JOIN users u ON u.id = f.owner_id
LEFT JOIN student_profiles p ON p.user_id = f.owner_id
ORDER BY f.id;
